import random

from nltk.corpus import wordnet
from nltk.tokenize import TreebankWordTokenizer
from nltk import pos_tag

AUG_OUTPUT_STOCHASTIC = True

_tokenizer = TreebankWordTokenizer()
_protected_tokens = {
    "not", "n't", "no", "never", "so", "such", "really", "totally",
    "obviously", "great", "wonderful", "perfect", "sure", "yeah",
    "oh", "wow",
}
_pos_map = {
    "NN": wordnet.NOUN,
    "NNS": wordnet.NOUN,
    "VB": wordnet.VERB,
    "VBD": wordnet.VERB,
    "VBG": wordnet.VERB,
    "VBN": wordnet.VERB,
    "VBP": wordnet.VERB,
    "VBZ": wordnet.VERB,
    "JJ": wordnet.ADJ,
    "JJR": wordnet.ADJ,
    "JJS": wordnet.ADJ,
    "RB": wordnet.ADV,
    "RBR": wordnet.ADV,
    "RBS": wordnet.ADV,
}

def _preserve_case(source, replacement):
    if source.isupper():
        return replacement.upper()
    if source[:1].isupper():
        return replacement[:1].upper() + replacement[1:]
    return replacement

def _rewrite_utterance(utterance):
    spans = list(_tokenizer.span_tokenize(utterance))
    tokens = [utterance[start:end] for start, end in spans]
    tagged = pos_tag(tokens)
    candidates = []

    for index, (token, tag) in enumerate(tagged):
        lower_token = token.lower()
        wn_pos = _pos_map.get(tag)
        if wn_pos is None or lower_token in _protected_tokens:
            continue
        if tag in {"NNP", "NNPS"}:
            continue

        synonyms = set()
        for synset in wordnet.synsets(token, pos=wn_pos):
            for lemma in synset.lemmas():
                name = lemma.name().replace("_", " ")
                if (
                    name.lower() != lower_token
                    and name.lower() not in _protected_tokens
                    and name.isalpha()
                ):
                    synonyms.add(name)

        if synonyms:
            candidates.append((index, sorted(synonyms)))

    if not candidates:
        return utterance

    replacement_count = min(
        4,
        max(1, int(len(candidates) * 0.1)),
    )
    selected = random.sample(candidates, min(replacement_count, len(candidates)))
    replacements = {
        index: _preserve_case(tokens[index], random.choice(synonyms))
        for index, synonyms in selected
    }

    output = []
    cursor = 0
    for index, (start, end) in enumerate(spans):
        output.append(utterance[cursor:start])
        output.append(replacements.get(index, utterance[start:end]))
        cursor = end
    output.append(utterance[cursor:])
    return "".join(output)

def aug_code(train_data):
    augmented = list(train_data)
    for record in train_data:
        rewritten = _rewrite_utterance(record["utterance"])
        augmented.append({
            **record,
            "utterance": rewritten,
        })
    return augmented

import re
import torch
from transformers import MarianMTModel, MarianTokenizer

AUG_OUTPUT_STOCHASTIC = False

_NEGATIONS = {"not", "n't", "no", "never"}
_INTENSIFIERS = {"so", "such", "really", "totally", "absolutely", "obviously", "just"}
_TERMINAL_PUNCTUATION = {".", "!", "?"}
_CUE_LEXICON = {
    "not", "n't", "no", "never", "so", "such", "really", "totally",
    "absolutely", "obviously", "just", "great", "perfect", "wonderful",
    "love",
}


def _tokens(text):
    tokens = re.findall(r"\b\w+(?:'\w+)?\b", text.lower())
    normalized = []
    for token in tokens:
        normalized.append(token)
        if token.endswith("n't"):
            normalized.append("n't")
    return normalized


def _has_terminal_punctuation(text):
    return bool(text) and text[-1] in _TERMINAL_PUNCTUATION


def _preserves_cues(source, candidate):
    source_tokens = set(_tokens(source))
    candidate_tokens = set(_tokens(candidate))

    for cue in _NEGATIONS:
        if cue in source_tokens and cue not in candidate_tokens:
            return False

    for cue in _INTENSIFIERS:
        if cue in source_tokens and cue not in candidate_tokens:
            return False

    if _has_terminal_punctuation(source) and not _has_terminal_punctuation(candidate):
        return False

    union = source_tokens | candidate_tokens
    jaccard = len(source_tokens & candidate_tokens) / len(union) if union else 1.0
    return jaccard >= 0.30


def _translate(texts, tokenizer, model, device):
    translated = []
    for start in range(0, len(texts), 32):
        batch = texts[start:start + 32]
        inputs = tokenizer(batch, return_tensors="pt", padding=True)
        inputs = {key: value.to(device) for key, value in inputs.items()}
        with torch.no_grad():
            generated = model.generate(**inputs, num_beams=4, max_length=128)
        translated.extend(tokenizer.batch_decode(generated, skip_special_tokens=True))
    return translated


def aug_code(train_data):
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    en_de_tokenizer = MarianTokenizer.from_pretrained("Helsinki-NLP/opus-mt-en-de")
    en_de_model = MarianMTModel.from_pretrained("Helsinki-NLP/opus-mt-en-de").to(device)
    en_de_model.eval()

    de_en_tokenizer = MarianTokenizer.from_pretrained("Helsinki-NLP/opus-mt-de-en")
    de_en_model = MarianMTModel.from_pretrained("Helsinki-NLP/opus-mt-de-en").to(device)
    de_en_model.eval()

    utterances = [record["utterance"] for record in train_data]
    german = _translate(utterances, en_de_tokenizer, en_de_model, device)
    paraphrases = _translate(german, de_en_tokenizer, de_en_model, device)

    augmented = list(train_data)
    for record, paraphrase in zip(train_data, paraphrases):
        rewritten = paraphrase if _preserves_cues(record["utterance"], paraphrase) else record["utterance"]
        new_record = dict(record)
        new_record["utterance"] = rewritten
        augmented.append(new_record)

    return augmented

