import nltk
from nltk.corpus import wordnet
from nltk.tokenize import TreebankWordDetokenizer

AUG_OUTPUT_STOCHASTIC = True

_DETOKENIZER = TreebankWordDetokenizer()
_POS_MAP = {
    "N": wordnet.NOUN,
    "V": wordnet.VERB,
    "J": wordnet.ADJ,
    "R": wordnet.ADV,
}

def _synonyms(token, tag):
    synsets = wordnet.synsets(token.lower(), pos=_POS_MAP[tag[0]])
    candidates = set()
    for synset in synsets:
        for lemma in synset.lemmas():
            name = lemma.name()
            if "_" not in name and name.isalpha() and name.lower() != token.lower():
                if token.isupper():
                    name = name.upper()
                elif token.istitle():
                    name = name.title()
                candidates.add(name)
    return list(candidates)

def _rewrite_sentence(sentence):
    tokens = nltk.word_tokenize(sentence, preserve_line=True)
    tagged = nltk.pos_tag(tokens)
    chunked = nltk.ne_chunk(tagged, binary=False)

    named_indices = set()
    offset = 0
    for item in chunked:
        if isinstance(item, nltk.Tree):
            leaf_count = len(item.leaves())
            named_indices.update(range(offset, offset + leaf_count))
            offset += leaf_count
        else:
            offset += 1

    candidates = []
    synonym_map = {}
    for index, (token, tag) in enumerate(tagged):
        if index in named_indices or not token.isalpha() or tag[0] not in _POS_MAP:
            continue
        synonyms = _synonyms(token, tag)
        if synonyms:
            candidates.append(index)
            synonym_map[index] = synonyms

    replace_count = int(len(candidates) * 0.12)
    for index in random.sample(candidates, replace_count):
        tokens[index] = random.choice(synonym_map[index])

    return _DETOKENIZER.detokenize(tokens)

def aug_code(train_data):
    augmented = list(train_data)

    for row in train_data:
        for _ in range(2):
            rewritten = dict(row)
            rewritten["context"] = [_rewrite_sentence(sentence) for sentence in row["context"]]
            rewritten["context_speakers"] = list(row["context_speakers"])
            augmented.append(rewritten)

    return augmented

