import re
from nltk import pos_tag
from nltk.corpus import wordnet

_TOKEN_RE = re.compile(r"[A-Za-z]+(?:['’][A-Za-z]+)?")

def _wordnet_pos(tag):
    if tag.startswith("NN"):
        return "n"
    if tag.startswith("VB"):
        return "v"
    if tag.startswith("JJ"):
        return "a"
    if tag.startswith("RB"):
        return "r"
    return None

def _replace_synonyms(text, ratio):
    matches = list(_TOKEN_RE.finditer(text))
    words = [m.group() for m in matches]
    tags = pos_tag(words)
    eligible = []

    for i, (word, tag) in enumerate(tags):
        lower = word.lower()
        wn_pos = _wordnet_pos(tag)
        if (
            wn_pos
            and lower not in {"not", "n't", "no", "never"}
            and not (i > 0 and word[:1].isupper())
        ):
            candidates = set()
            for synset in wordnet.synsets(lower, pos=wn_pos):
                for lemma in synset.lemmas():
                    candidate = lemma.name().replace("_", " ")
                    if (
                        candidate.lower() != lower
                        and " " not in candidate
                        and candidate.isalpha()
                    ):
                        candidates.add(candidate)
            if candidates:
                eligible.append((i, sorted(candidates)))

    count = int(len(eligible) * ratio)
    selected = random.sample(eligible, count) if count else []
    replacements = {
        i: random.choice(candidates)
        for i, candidates in selected
    }

    pieces = []
    cursor = 0
    for i, match in enumerate(matches):
        pieces.append(text[cursor:match.start()])
        replacement = replacements.get(i, match.group())
        if replacement and match.group()[:1].isupper():
            replacement = replacement[0].upper() + replacement[1:]
        pieces.append(replacement)
        cursor = match.end()
    pieces.append(text[cursor:])
    return "".join(pieces)

def aug_code(train_data):
    augmented = list(train_data)

    for record in train_data:
        for _ in range(2):
            rewritten = dict(record)
            rewritten["utterance"] = _replace_synonyms(
                record["utterance"], 0.1
            )
            rewritten["context"] = [
                _replace_synonyms(sentence, 0.1)
                for sentence in record["context"]
            ]
            rewritten["context_speakers"] = list(record["context_speakers"])
            augmented.append(rewritten)

    return augmented

