def _anonymize_text(value, pattern, replacements):
    return pattern.sub(lambda match: replacements[match.group(0).casefold()], value)

def aug_code(train_data):
    augmented = list(train_data)

    for row in train_data:
        name_order = []
        name_keys = set()

        for name in [row["speaker"]] + list(row["context_speakers"]):
            key = name.casefold()
            if name and key not in name_keys:
                name_keys.add(key)
                name_order.append(key)

        replacements = {
            key: f"SPEAKER_{index}"
            for index, key in enumerate(name_order, start=1)
        }

        if name_order:
            pattern = re.compile(
                r"(?<!\w)(?:"
                + "|".join(
                    sorted((re.escape(name) for name in name_order), key=len, reverse=True)
                )
                + r")(?!\w)",
                re.IGNORECASE,
            )

            anonymized = dict(row)
            anonymized["speaker"] = replacements[row["speaker"].casefold()]
            anonymized["context_speakers"] = [
                replacements[name.casefold()] for name in row["context_speakers"]
            ]
            anonymized["utterance"] = _anonymize_text(
                row["utterance"], pattern, replacements
            )
            anonymized["context"] = [
                _anonymize_text(text, pattern, replacements)
                for text in row["context"]
            ]
            augmented.append(anonymized)

    return augmented

