def _shuffle_utterance(utterance):
    tokens = utterance.split()
    if len(tokens) <= 2:
        return utterance

    first = tokens[0]
    last = tokens[-1]
    interior = tokens[1:-1]

    terminal_match = re.search(r"([.!?,;:。！？])$", last)
    terminal_punctuation = ""
    if terminal_match:
        terminal_punctuation = terminal_match.group(1)
        last = last[:-len(terminal_punctuation)]

    if last:
        interior.append(last)

    for window_index in range(2):
        start = window_index * 3
        window = interior[start:start + 3]
        if len(window) == 3:
            random.shuffle(window)
            interior[start:start + 3] = window

    if terminal_punctuation:
        final_token = interior.pop()
        last = final_token + terminal_punctuation
    else:
        last = interior.pop()

    return " ".join([first] + interior + [last])

def aug_code(train_data):
    augmented = list(train_data)
    for record in train_data:
        rewritten = dict(record)
        rewritten["utterance"] = _shuffle_utterance(record["utterance"])
        augmented.append(rewritten)
    return augmented

