import re
import torch
from transformers import AutoModelForSeq2SeqLM, AutoTokenizer

AUG_OUTPUT_STOCHASTIC = False

_MODEL_CACHE = {}

_PIVOT_MODELS = {
    "de": ("Helsinki-NLP/opus-mt-en-de", "Helsinki-NLP/opus-mt-de-en"),
    "ru": ("Helsinki-NLP/opus-mt-en-ru", "Helsinki-NLP/opus-mt-ru-en"),
    "ja": ("Helsinki-NLP/opus-mt-en-jap", "Helsinki-NLP/opus-mt-jap-en"),
}

_CUE_LEXICONS = {
    "intensifiers": {
        "very", "really", "so", "extremely", "totally", "absolutely",
        "incredibly", "utterly", "super", "literally", "highly", "too"
    },
    "negation": {
        "not", "no", "never", "neither", "nor", "nothing", "nobody",
        "nowhere", "hardly", "barely", "isn't", "wasn't", "weren't",
        "don't", "doesn't", "didn't", "can't", "couldn't", "won't",
        "wouldn't", "shouldn't"
    },
    "interjections": {
        "oh", "ah", "aha", "wow", "ugh", "huh", "hey", "ouch", "oops",
        "well", "gee", "yay", "alas"
    },
    "hyperbole": {
        "best", "worst", "ever", "forever", "million", "genius", "perfect",
        "amazing", "awesome", "unbelievable", "incredible", "literally"
    },
}

def _clone_record(record):
    cloned = dict(record)
    if "context" in cloned:
        cloned["context"] = list(cloned["context"])
    if "context_speakers" in cloned:
        cloned["context_speakers"] = list(cloned["context_speakers"])
    return cloned

def _tokens(text):
    return set(re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?", text.lower()))

def _terminal_punctuation(text):
    match = re.search(r"([.!?…]+)$", text)
    return match.group(1) if match else ""

def _edit_distance_ratio(left, right):
    return 1.0 - difflib.SequenceMatcher(None, left, right).ratio()

def _load_translation_models(pivot, device):
    if pivot not in _MODEL_CACHE:
        forward_name, backward_name = _PIVOT_MODELS[pivot]
        forward_tokenizer = AutoTokenizer.from_pretrained(forward_name)
        forward_model = AutoModelForSeq2SeqLM.from_pretrained(forward_name)
        backward_tokenizer = AutoTokenizer.from_pretrained(backward_name)
        backward_model = AutoModelForSeq2SeqLM.from_pretrained(backward_name)
        _MODEL_CACHE[pivot] = (
            forward_tokenizer,
            forward_model,
            backward_tokenizer,
            backward_model,
        )

    forward_tokenizer, forward_model, backward_tokenizer, backward_model = _MODEL_CACHE[pivot]
    forward_model.to(device)
    backward_model.to(device)
    forward_model.eval()
    backward_model.eval()
    return (
        forward_tokenizer,
        forward_model,
        backward_tokenizer,
        backward_model,
    )

def _translate(text, pivot, device):
    (
        forward_tokenizer,
        forward_model,
        backward_tokenizer,
        backward_model,
    ) = _load_translation_models(pivot, device)

    with torch.inference_mode():
        forward_inputs = forward_tokenizer(
            text,
            return_tensors="pt",
            padding=True,
        ).to(device)
        pivot_ids = forward_model.generate(
            **forward_inputs,
            num_beams=4,
            do_sample=False,
            max_length=512,
        )
        pivot_text = forward_tokenizer.batch_decode(
            pivot_ids,
            skip_special_tokens=True,
        )[0]

        backward_inputs = backward_tokenizer(
            pivot_text,
            return_tensors="pt",
            padding=True,
        ).to(device)
        english_ids = backward_model.generate(
            **backward_inputs,
            num_beams=4,
            do_sample=False,
            max_length=512,
        )
        return backward_tokenizer.batch_decode(
            english_ids,
            skip_special_tokens=True,
        )[0]

def aug_code(train_data):
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    fold_text = " ".join(record["utterance"] for record in train_data)
    fold_tokens = _tokens(fold_text)
    fold_lexicons = {
        category: cues & fold_tokens
        for category, cues in _CUE_LEXICONS.items()
    }

    augmented = []
    for source_record in train_data:
        source = _clone_record(source_record)
        augmented.append(source)

        utterance = source_record["utterance"]
        source_tokens = _tokens(utterance)
        source_terminal = _terminal_punctuation(utterance)

        candidates = []
        for pivot_index, pivot in enumerate(("de", "ru", "ja")):
            paraphrase = _translate(utterance, pivot, device)
            paraphrase_tokens = _tokens(paraphrase)

            cues_preserved = True
            for cue_words in fold_lexicons.values():
                source_cues = source_tokens & cue_words
                if source_cues and not (paraphrase_tokens & cue_words):
                    cues_preserved = False
                    break

            if source_terminal and _terminal_punctuation(paraphrase) != source_terminal:
                cues_preserved = False

            if cues_preserved and _edit_distance_ratio(utterance, paraphrase) >= 0.15:
                candidates.append((pivot_index, paraphrase))

        valid_pairs = []
        for first_index in range(len(candidates)):
            for second_index in range(first_index + 1, len(candidates)):
                first = candidates[first_index][1]
                second = candidates[second_index][1]
                if _edit_distance_ratio(first, second) >= 0.15:
                    score = (
                        difflib.SequenceMatcher(None, utterance, first).ratio()
                        + difflib.SequenceMatcher(None, utterance, second).ratio()
                        + difflib.SequenceMatcher(None, first, second).ratio()
                    )
                    valid_pairs.append((score, first_index, second_index))

        if valid_pairs:
            _, first_index, second_index = min(
                valid_pairs,
                key=lambda item: (item[0], candidates[item[1]][0], candidates[item[2]][0]),
            )
            selected = [
                candidates[first_index][1],
                candidates[second_index][1],
            ]
        else:
            selected = [
                paraphrase
                for _, paraphrase in candidates
                if paraphrase != utterance
            ][:2]

        generated = []
        for paraphrase in selected:
            if paraphrase == utterance or paraphrase in generated:
                continue
            generated.append(paraphrase)
            rewritten = _clone_record(source_record)
            rewritten["utterance"] = paraphrase
            augmented.append(rewritten)

    return augmented

