def aug_code(train_data):
    augmented = copy.deepcopy(train_data)
    donor_pool = {}

    for index, row in enumerate(train_data):
        donor_pool.setdefault(row["sarcasm"], []).append(index)

    for source_index, source_row in enumerate(train_data):
        candidates = [
            index
            for index in donor_pool[source_row["sarcasm"]]
            if index != source_index
        ]

        for _ in range(2):
            if not candidates:
                continue

            donor_row = train_data[random.choice(candidates)]
            donor_context = list(donor_row["context"])
            donor_context_speakers = list(donor_row["context_speakers"])

            if donor_context_speakers:
                target_speaker = source_row["speaker"]
                if donor_context_speakers[-1] == target_speaker:
                    alternatives = [
                        speaker
                        for speaker in donor_context_speakers
                        if speaker != target_speaker
                    ]
                    if alternatives:
                        donor_context_speakers[-1] = alternatives[0]

            augmented.append({
                "utterance": source_row["utterance"],
                "speaker": source_row["speaker"],
                "context": donor_context,
                "context_speakers": donor_context_speakers,
                "sarcasm": source_row["sarcasm"],
            })

    deduplicated = []
    seen = set()

    for row in augmented:
        key = (
            row["utterance"],
            row["speaker"],
            tuple(row["context"]),
            tuple(row["context_speakers"]),
            row["sarcasm"],
        )
        if key not in seen:
            seen.add(key)
            deduplicated.append(row)

    return deduplicated

