import re
from collections import Counter

AUG_OUTPUT_STOCHASTIC = True


def aug_code(train_data):
    name_counts = Counter()

    for row in train_data:
        name_counts[row["speaker"]] += 1
        name_counts.update(row["context_speakers"])

    vocabulary = list(name_counts)
    augmented = list(train_data)

    for row in train_data:
        identities = list(dict.fromkeys(
            [row["speaker"]] + row["context_speakers"]
        ))
        if not identities:
            continue

        mappings = []

        for _ in range(2):
            mapping = None

            for _ in range(100):
                targets = random.sample(vocabulary, len(identities))
                candidate = dict(zip(identities, targets))

                if any(candidate[name] == name for name in identities):
                    continue

                signature = tuple(candidate[name] for name in identities)
                if any(
                    signature == tuple(previous[name] for name in identities)
                    for previous in mappings
                ):
                    continue

                mapping = candidate
                break

            if mapping is None:
                continue

            mappings.append(mapping)

            text_pattern = re.compile(
                r"(?<!\w)(?:"
                + "|".join(
                    re.escape(name)
                    for name in sorted(mapping, key=len, reverse=True)
                )
                + r")(?!\w)"
            )

            def rewrite_text(value):
                return text_pattern.sub(
                    lambda match: mapping[match.group(0)],
                    value,
                )

            rewritten = dict(row)
            rewritten["speaker"] = mapping.get(row["speaker"], row["speaker"])
            rewritten["context_speakers"] = [
                mapping.get(name, name)
                for name in row["context_speakers"]
            ]
            rewritten["utterance"] = rewrite_text(row["utterance"])
            rewritten["context"] = [
                rewrite_text(value)
                for value in row["context"]
            ]

            if rewritten != row:
                augmented.append(rewritten)

    return augmented

