import numpy as np
import torch
from nltk.corpus import wordnet
from sklearn.model_selection import StratifiedKFold
from sklearn.svm import LinearSVC
from transformers import BertForMaskedLM, BertModel, BertTokenizerFast


AUG_OUTPUT_STOCHASTIC = True


def _load_models():
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    tokenizer = BertTokenizerFast.from_pretrained("bert-base-uncased")
    encoder = BertModel.from_pretrained("bert-base-uncased").to(device)
    mlm = BertForMaskedLM.from_pretrained("bert-base-uncased").to(device)
    encoder.eval()
    mlm.eval()
    return tokenizer, encoder, mlm, device


def _record_text(record):
    return record["utterance"] + " " + " ".join(record["context"])


def _extract_embeddings(records, tokenizer, encoder, device, batch_size=16):
    embeddings = []

    for start in range(0, len(records), batch_size):
        batch = records[start:start + batch_size]
        texts = [_record_text(record) for record in batch]
        encoded = tokenizer(
            texts,
            padding=True,
            truncation=True,
            max_length=512,
            return_tensors="pt",
        )
        encoded = {key: value.to(device) for key, value in encoded.items()}

        with torch.no_grad():
            hidden = encoder(**encoded).last_hidden_state
            mask = encoded["attention_mask"].unsqueeze(-1)
            pooled = (hidden * mask).sum(dim=1) / mask.sum(dim=1).clamp_min(1)
            embeddings.append(pooled.cpu().numpy())

    return np.concatenate(embeddings, axis=0)


def _wordnet_paraphrase(text, ratio):
    spans = list(re.finditer(r"[A-Za-z]+", text))
    count = int(len(spans) * ratio)
    if count == 0:
        return text

    selected = set(random.sample(range(len(spans)), min(count, len(spans))))
    replacements = {}

    for index in selected:
        word = spans[index].group(0)
        candidates = set()

        for synset in wordnet.synsets(word):
            for lemma in synset.lemmas():
                candidate = lemma.name().replace("_", " ")
                if candidate.lower() != word.lower() and candidate.isalpha():
                    candidates.add(candidate)

        if candidates:
            replacements[index] = random.choice(sorted(candidates))

    parts = []
    last_end = 0
    for index, span in enumerate(spans):
        parts.append(text[last_end:span.start()])
        parts.append(replacements.get(index, span.group(0)))
        last_end = span.end()
    parts.append(text[last_end:])

    return "".join(parts)


def _mlm_paraphrase(text, tokenizer, mlm, device, ratio):
    encoded = tokenizer(
        text,
        return_offsets_mapping=True,
        truncation=True,
        max_length=512,
        return_tensors="pt",
    )
    offsets = encoded.pop("offset_mapping")[0].tolist()
    input_ids = encoded["input_ids"][0]
    eligible = [
        index
        for index, (start, end) in enumerate(offsets)
        if end > start and input_ids[index].item() not in {
            tokenizer.cls_token_id,
            tokenizer.sep_token_id,
        }
    ]

    count = int(len(eligible) * ratio)
    if count == 0:
        return text

    masked = random.sample(eligible, min(count, len(eligible)))
    encoded = {key: value.to(device) for key, value in encoded.items()}
    masked_ids = encoded["input_ids"].clone()

    for index in masked:
        masked_ids[0, index] = tokenizer.mask_token_id

    encoded["input_ids"] = masked_ids

    with torch.no_grad():
        logits = mlm(**encoded).logits[0]

    for index in masked:
        masked_ids[0, index] = torch.argmax(logits[index])

    return tokenizer.decode(masked_ids[0], skip_special_tokens=True)


def _paraphrase(text, method, tokenizer, mlm, device):
    if method == 0:
        return _wordnet_paraphrase(text, 0.15)
    return _mlm_paraphrase(text, tokenizer, mlm, device, 0.15)


def aug_code(train_data):
    augmented = [copy.deepcopy(record) for record in train_data]
    tokenizer, encoder, mlm, device = _load_models()

    labels = np.asarray([record["sarcasm"] for record in train_data])
    features = _extract_embeddings(train_data, tokenizer, encoder, device)

    margins = np.zeros(len(train_data), dtype=float)
    splitter = StratifiedKFold(n_splits=5, shuffle=True)

    for fit_indices, holdout_indices in splitter.split(features, labels):
        probe = LinearSVC()
        probe.fit(features[fit_indices], labels[fit_indices])
        margins[holdout_indices] = probe.decision_function(features[holdout_indices])

    selected_indices = []
    for label in np.unique(labels):
        label_indices = np.flatnonzero(labels == label)
        selected_count = int(len(label_indices) * 0.3)
        ordered = label_indices[np.argsort(np.abs(margins[label_indices]))]
        selected_indices.extend(ordered[:selected_count].tolist())

    for source_index in selected_indices:
        source = train_data[source_index]
        seen = {source["utterance"]}

        for copy_index in range(5):
            generated = None

            for _ in range(20):
                candidate = _paraphrase(
                    source["utterance"],
                    copy_index % 2,
                    tokenizer,
                    mlm,
                    device,
                )
                if candidate not in seen:
                    generated = candidate
                    break

            if generated is not None:
                record = copy.deepcopy(source)
                record["utterance"] = generated
                augmented.append(record)
                seen.add(generated)

    return augmented

