def _wordnet_pos(token):
    synsets = []
    for pos in ("n", "v", "a"):
        synsets.extend(wordnet.synsets(token, pos=pos))
    if not synsets:
        return None
    return synsets[0].pos()

def _is_cue_token(token, utterance):
    lower = token.lower()
    if lower in {
        "very", "really", "so", "too", "quite", "absolutely", "totally",
        "extremely", "incredibly", "never", "not", "no", "n't", "nothing",
        "nobody", "nowhere", "neither", "nor", "hardly", "barely",
        "always", "literally", "just"
    }:
        return True
    if any(mark in token for mark in "\"'“”‘’"):
        return True
    if not re.fullmatch(r"[A-Za-z]+", token):
        return True
    if re.search(r"[!?]{1,}|\.{2,}|[A-Za-z][!?]+", utterance):
        return any(mark in token for mark in "!?")
    return False

def _synonym_edit(utterance):
    tokens = re.findall(r"[A-Za-z]+(?:'[A-Za-z]+)?|[^A-Za-z\s]", utterance)
    candidates = []
    for index, token in enumerate(tokens):
        if not re.fullmatch(r"[A-Za-z]+(?:'[A-Za-z]+)?", token):
            continue
        if _is_cue_token(token, utterance):
            continue
        pos = _wordnet_pos(token.lower())
        if pos not in {"n", "v", "a"}:
            continue
        candidates.append((index, token, pos))

    count = int(len(candidates) * 0.15)
    if count <= 0:
        return utterance

    for index, token, pos in random.sample(candidates, min(count, len(candidates))):
        synsets = wordnet.synsets(token.lower(), pos=pos)
        lemmas = []
        for synset in synsets:
            for lemma in synset.lemmas():
                replacement = lemma.name().replace("_", " ")
                if replacement.lower() != token.lower() and replacement not in lemmas:
                    lemmas.append(replacement)
        if lemmas:
            replacement = random.choice(lemmas)
            if token[:1].isupper():
                replacement = replacement[:1].upper() + replacement[1:]
            tokens[index] = replacement

    result = ""
    for token in tokens:
        if not result:
            result = token
        elif re.fullmatch(r"[,.!?;:%)\]}]", token):
            result += token
        elif token in {"'s", "'re", "'ve", "n't"}:
            result += token
        elif result.endswith(("(", "[", "{", "$")):
            result += token
        else:
            result += " " + token
    return result

