        features[token] = features.get(token, 0.0) + 1.0
    for i in range(max(0, len(text) - 2)):
        gram = text[i:i + 3]
        key = "#" + gram
        features[key] = features.get(key, 0.0) + 0.25
    return features


def _dot(weights, features):
    return sum(weights.get(key, 0.0) * value for key, value in features.items())


def _fit_probe(features, labels, held_out):
    weights = {}
    bias = 0.0
    training = [i for i in range(len(features)) if i != held_out]
    if not training:
        return weights, bias

    for _ in range(8):
        for i in training:
            target = 1.0 if labels[i] else -1.0
            score = _dot(weights, features[i]) + bias
            if target * score <= 1.0:
                for key, value in features[i].items():
                    weights[key] = weights.get(key, 0.0) + target * value
                bias += target
    return weights, bias


def _difficulty_scores(records):
    features = [_text_features(record) for record in records]
    labels = [_label_value(record["sarcasm"]) for record in records]
    scores = []

    for index in range(len(records)):
        weights, bias = _fit_probe(features, labels, index)
        score = _dot(weights, features[index]) + bias
        signed_margin = score if labels[index] else -score
        predicted = 1 if score >= 0.0 else 0
        misclassified = predicted != labels[index]
        scores.append((0 if misclassified else 1, signed_margin, index))

    return sorted(scores)


