_TOKEN_RE = re.compile(r"[A-Za-z]+(?:'[A-Za-z]+)?|\d+(?:\.\d+)?|[^\w\s]")

_NEGATIONS = {
    "no", "not", "never", "neither", "nor", "n't", "cannot", "can't",
    "couldn't", "wouldn't", "shouldn't", "won't", "isn't", "aren't",
    "wasn't", "weren't", "don't", "doesn't", "didn't", "haven't",
    "hasn't", "hadn't"
}

_INTENSIFIERS = {
    "very", "really", "so", "too", "quite", "extremely", "highly",
    "especially", "absolutely", "totally", "completely", "utterly",
    "incredibly", "particularly", "strongly", "deeply", "super",
    "more", "most", "much", "far", "pretty", "rather", "such"
}

_STOPWORDS = {
    "a", "an", "the", "and", "or", "but", "if", "then", "than", "as",
    "of", "to", "in", "on", "at", "by", "for", "from", "with", "about",
    "into", "over", "after", "before", "between", "during", "through",
    "is", "am", "are", "was", "were", "be", "been", "being", "do",
    "does", "did", "have", "has", "had", "i", "you", "he", "she", "it",
    "we", "they", "me", "him", "her", "us", "them", "my", "your", "his",
    "its", "our", "their", "this", "that", "these", "those", "who",
    "what", "which", "where", "when", "why", "how", "all", "any",
    "some", "not", "no", "yes", "can", "could", "will", "would", "shall",
    "should", "may", "might", "must", "there", "here", "also", "just",
    "than", "because", "while", "until", "both", "each", "few", "many"
}

def _tokens(text):
    return list(_TOKEN_RE.finditer(text))

def _coarse_pos(token):
    word = token.lower()
    if not re.match(r"^[A-Za-z]+(?:'[A-Za-z]+)?$", token):
        return None
    if word in _STOPWORDS:
        return None
    if word.endswith(("ly", "ward", "wise")):
        return "adv"
    if word.endswith(("ing", "ed", "en", "ify", "ise", "ize")):
        return "verb"
    if word.endswith(("ous", "ful", "less", "ive", "able", "ible", "al",
                       "ic", "ish", "ary", "y")):
        return "adj"
    return "noun"

def _is_named_entity(token_matches, index):
    token = token_matches[index].group(0)
    if not re.match(r"^[A-Za-z]+(?:'[A-Za-z]+)?$", token):
        return False
    if token.isupper() and len(token) > 1:
        return True
    if token[:1].isupper():
        if index > 0:
            previous = token_matches[index - 1].group(0)
            if previous not in {".", "!", "?"}:
                return True
        if index + 1 < len(token_matches):
            following = token_matches[index + 1].group(0)
            if following[:1].isupper() and following.isalpha():
                return True
    return False

def _clone_record(record, utterance=None):
    cloned = dict(record)
    cloned["context"] = list(record["context"])
    cloned["context_speakers"] = list(record["context_speakers"])
    if utterance is not None:
        cloned["utterance"] = utterance
    return cloned

def _record_key(record):
    return (
        record["utterance"],
        record["speaker"],
        tuple(record["context"]),
        tuple(record["context_speakers"]),
        record["sarcasm"]
    )

def aug_code(train_data):
    rows = [_clone_record(row) for row in train_data]

    token_counts = {}
    label_counts = {}
    joint_counts = {}
    total_rows = len(rows)

    for row in rows:
        label = row["sarcasm"]
        label_counts[label] = label_counts.get(label, 0) + 1
        seen = set()
        for match in _tokens(row["utterance"]):
            token = match.group(0).lower()
            seen.add(token)
        for token in seen:
            token_counts[token] = token_counts.get(token, 0) + 1
            pair = (token, label)
            joint_counts[pair] = joint_counts.get(pair, 0) + 1

    protected_by_label = {}
    for label, label_count in label_counts.items():
        scored = []
        for token, token_count in token_counts.items():
            joint = joint_counts.get((token, label), 0)
            if joint:
                pmi = math.log(
                    (joint * total_rows) / (token_count * label_count)
                )
                scored.append((pmi, token))
        scored.sort(key=lambda item: (-item[0], item[1]))
        protected_by_label[label] = {
            token for _, token in scored[:150]
        }

    donor_pools = {}
    for row_index, row in enumerate(rows):
        label = row["sarcasm"]
        matches = _tokens(row["utterance"])
        for other_index, other in enumerate(rows):
            if other_index == row_index or other["sarcasm"] != label:
                continue
            other_matches = _tokens(other["utterance"])
            for other_match in other_matches:
                word = other_match.group(0)
                pos = _coarse_pos(word)
                if pos is not None:
                    donor_pools.setdefault((label, pos), []).append(word)

    augmented = list(rows)
    seen_records = {_record_key(row) for row in rows}

    for row_index, row in enumerate(rows):
        label = row["sarcasm"]
        matches = _tokens(row["utterance"])
        replaceable = []

        for index, match in enumerate(matches):
            token = match.group(0)
            normalized = token.lower()
            protected = (
                not _coarse_pos(token)
                or normalized in protected_by_label.get(label, set())
                or normalized in _NEGATIONS
                or normalized in _INTENSIFIERS
                or _is_named_entity(matches, index)
            )
            if not protected:
                replaceable.append((index, match, _coarse_pos(token)))

        replacement_count = int(len(replaceable) * 0.25)

        for _ in range(2):
            selected = set(random.sample(
                replaceable,
                min(replacement_count, len(replaceable))
            ))
            replacements = {}

            for index, match, pos in replaceable:
                if (index, match, pos) in selected:
                    donors = donor_pools.get((label, pos), [])
                    if donors:
                        replacements[index] = random.choice(donors)

            pieces = []
            cursor = 0
            for index, match in enumerate(matches):
                pieces.append(row["utterance"][cursor:match.start()])
                pieces.append(replacements.get(index, match.group(0)))
                cursor = match.end()
            pieces.append(row["utterance"][cursor:])

            candidate = _clone_record(row, "".join(pieces))
            key = _record_key(candidate)
            if key not in seen_records:
                augmented.append(candidate)
                seen_records.add(key)

    return augmented

